def compromisos_a_actividades(apps, schema_editor):
    """El compromiso deja de ser una tabla: es la actividad que está en el Tubo de Trabajo.
    1) Los estados antiguos pasan a los nuevos: Corregir y Rechazar quedan como RECHAZAR (la evidencia no es
       válida y se resube; la actividad no se anula).
    2) Cada compromiso traspasa su fecha límite y territorio a su actividad; si no tenía actividad, se crea una.
    3) Una actividad sin evidencia queda EN_TUBO (es un compromiso)."""
    Actividad = apps.get_model('ActividadesApp', 'Actividad')
    Evidencia = apps.get_model('ActividadesApp', 'Evidencia')
    Validacion = apps.get_model('ActividadesApp', 'Validacion')
    Compromiso = apps.get_model('ActividadesApp', 'Compromiso')
    Catalogo = apps.get_model('UsuarioApp', 'Catalogo')
    Periodo = apps.get_model('IndicadoresApp', 'Periodo')

    Validacion.objects.filter(decision='CORREGIR').update(decision='RECHAZAR')
    Evidencia.objects.filter(estado_revision='OBSERVADA').update(estado_revision='RECHAZADA')

    for compromiso in Compromiso.objects.all():
        actividades = list(Actividad.objects.filter(compromiso_id=compromiso.pk))
        if not actividades:
            item = Catalogo.objects.filter(tipo='ITEM_GESTION').order_by('id').first()
            fecha = compromiso.fecha_registro.date()
            periodo = (Periodo.objects.filter(fecha_inicio__lte=fecha, fecha_termino__gte=fecha).first()
                       or Periodo.objects.order_by('-fecha_inicio').first())
            if item is None or periodo is None:
                continue
            actividades = [Actividad.objects.create(
                fecha=compromiso.fecha_registro, solicitud_problema=compromiso.observacion,
                accion=compromiso.origen[:255], contacto=compromiso.solicitante[:255], item=item,
                periodo=periodo, usuario_id=compromiso.responsable_id, estado='REGISTRADA')]
        for actividad in actividades:
            actividad.ingreso_agenda_colectiva = True
            actividad.fecha_comprometida = compromiso.fecha_comprometida
            actividad.territorio = compromiso.territorio[:150]
            actividad.save()

    for actividad in Actividad.objects.all():
        vigente = Evidencia.objects.filter(actividad=actividad).order_by('-version').first()
        if vigente is None:
            actividad.estado = 'EN_TUBO'
            actividad.ingreso_agenda_colectiva = True
            if actividad.fecha_comprometida is None:
                actividad.fecha_comprometida = actividad.periodo.fecha_termino
        elif vigente.estado_revision == 'APROBADA':
            actividad.estado = 'VALIDADA'
        elif vigente.estado_revision == 'RECHAZADA':
            actividad.estado = 'RECHAZADA'
        else:
            actividad.estado = 'REGISTRADA'
        actividad.save()


def no_revertir(apps, schema_editor):
    pass


